package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import com.ruoyi.medical.contracts.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
import static com.ruoyi.medical.persistence.RegistrationLifecycleSchema.*;

/** Source-backed, path-specific checks; no embedded invented IVD catalogue or legal eligibility decision. */
final class RegistrationLifecyclePipeline {
 private RegistrationLifecyclePipeline(){}
 static JsonNode plan(JsonNode fixed)throws Exception{
  var schema=new RegistrationLifecycleSchema();var s=schema.read(fixed.required("selection"));var out=(ObjectNode)schema.tree(Map.of("schema_version","1.0.0","scenario_kind",s.scenarioKind(),"human_review_required",true,"legal_approval",false,"conclusion_authority","MACHINE_CHECK_NOT_REGULATORY_APPROVAL"));var reasons=out.putArray("unknown_reasons");
  requireFact(s,s.pathDecision(),"PATH_DECISION",Set.of("APPROVED_DECISION"),reasons);
  try{var d=schema.decision(s.pathDecision().text());String history=s instanceof ChangeSelection c?c.historySourceKey():s instanceof RenewalSelection r?r.historySourceKey():"";if(!s.scenarioKind().equals(d.scenarioKind())||!s.productCategory().equals(d.productCategory())||!"APPROVED".equals(d.outcome())||!s.catalogueSourceKey().equals(d.catalogueSourceKey())||!s.templateVersion().version_id().equals(d.templateVersion())||!history.equals(d.historySourceKey()))reasons.add("PROFESSIONAL_PATH_DECISION_CONFLICT");}catch(com.fasterxml.jackson.core.JsonProcessingException|IllegalArgumentException|NullPointerException e){reasons.add("PROFESSIONAL_PATH_DECISION_MISSING_OR_UNREADABLE");}
  // Catalogue is supplied as an approved source, never synthesized from the first-registration template.
  if(s.catalogueSourceKey().isEmpty())reasons.add(IVD.equals(s.scenarioKind())?"IVD_APPROVED_CATALOGUE_MISSING":"PATH_APPROVED_CATALOGUE_MISSING");
  else try{var src=source(s,s.catalogueSourceKey());var c=schema.catalogue(src.literal());if(!"CATALOGUE".equals(src.nature())||!s.scenarioKind().equals(c.scenarioKind())||!s.productCategory().equals(c.productCategory())||c.authority().isBlank()||c.edition().isBlank()||c.effectiveDate().isBlank()||c.items().isEmpty())reasons.add("CATALOGUE_PATH_OR_AUTHORITY_CONFLICT");var approved=new LinkedHashMap<String,String>();for(var i:c.items())if(i.key().isBlank()||i.title().isBlank()||approved.put(i.key(),i.title())!=null)reasons.add("CATALOGUE_ITEM_INVALID");var declared=new LinkedHashMap<String,String>();for(var i:s.directory())declared.put(i.key(),i.title());if(!approved.equals(declared))reasons.add("APPROVED_CATALOGUE_DIRECTORY_MISMATCH");}catch(com.fasterxml.jackson.core.JsonProcessingException|IllegalArgumentException|NullPointerException e){reasons.add("APPROVED_CATALOGUE_UNREADABLE");}
  if(s.directory().isEmpty())reasons.add("PATH_DIRECTORY_EMPTY");
  for(var d:s.directory()){requireFact(s,d.basis(),"DIRECTORY_APPLICABILITY:"+d.key(),Set.of("APPROVED_DECISION"),reasons);try{var decision=schema.applicabilityDecision(d.basis().text());if(!s.scenarioKind().equals(decision.scenarioKind())||!d.key().equals(decision.directoryKey())||!d.applicability().equals(decision.outcome())||!d.evidenceSourceKeys().equals(decision.evidenceSourceKeys()))reasons.add("DIRECTORY_APPROVAL_CONTEXT_CONFLICT:"+d.key());}catch(Exception e){reasons.add("DIRECTORY_APPROVAL_UNREADABLE:"+d.key());}if("UNKNOWN".equals(d.applicability()))reasons.add("DIRECTORY_APPLICABILITY_UNKNOWN:"+d.key());if("REQUIRED".equals(d.applicability())){requireBody(s,d.key(),reasons);if(d.evidenceSourceKeys().isEmpty())reasons.add("DIRECTORY_EVIDENCE_MISSING:"+d.key());}}
  if(s instanceof IvdSelection i){requireBody(s,"IVD_PRODUCT",reasons);requireFact(s,i.intendedUse(),"IVD_INTENDED_USE",Set.of("CURRENT_DOCUMENT","APPROVED_DECISION"),reasons);requireFact(s,i.reagentClassification(),"IVD_CLASSIFICATION",Set.of("APPROVED_DECISION","RULE"),reasons);if(!hasNature(s,i.analyticalEvidenceSourceKeys(),"ANALYTICAL"))reasons.add("IVD_ANALYTICAL_EVIDENCE_MISSING");if(!hasNature(s,i.clinicalEvidenceSourceKeys(),"CLINICAL"))reasons.add("IVD_CLINICAL_EVIDENCE_MISSING");}
  if(s instanceof ChangeSelection c){checkHistory(s,c.history(),c.historySourceKey(),schema,reasons);if(c.changes().isEmpty())reasons.add("CHANGE_ITEMS_MISSING");for(var x:c.changes()){requireBody(s,x.key(),reasons);int index=0;for(var f:changeFacts(x))requireFact(s,f,"CHANGE:"+x.key()+":"+(index++),Set.of(),reasons);requireFact(s,x.validation(),"CHANGE_VALIDATION:"+x.key(),Set.of("VALIDATION","APPROVED_DECISION"),reasons);requireFact(s,x.clinicalImpact(),"CHANGE_CLINICAL_IMPACT:"+x.key(),Set.of("CLINICAL","APPROVED_DECISION"),reasons);requireFact(s,x.riskImpact(),"CHANGE_RISK_IMPACT:"+x.key(),Set.of("VALIDATION","APPROVED_DECISION"),reasons);if(x.beforeDocumentSourceKeys().isEmpty()||x.afterDocumentSourceKeys().isEmpty())reasons.add("CHANGE_BEFORE_AFTER_DOCUMENTS_MISSING:"+x.key());if(x.before().text().equals(x.after().text()))reasons.add("CHANGE_ORIGINAL_VALUES_IDENTICAL:"+x.key());}}
  if(s instanceof RenewalSelection r){checkHistory(s,r.history(),r.historySourceKey(),schema,reasons);for(String group:List.of("CERTIFICATE_VALIDITY","MANDATORY_STANDARD_UPDATE","CONTINUING_STUDY","CHANGED_TECHNICAL_REQUIREMENTS"))if(r.conditions().stream().noneMatch(c->group.equals(c.group())))reasons.add("RENEWAL_CONDITION_MISSING:"+group);for(var c:r.conditions()){requireBody(s,c.key(),reasons);requireFact(s,c.criterion(),"RENEWAL_CRITERION:"+c.key(),Set.of("RULE","ORIGINAL_CERTIFICATE","APPROVED_DECISION"),reasons);requireFact(s,c.assessment(),"RENEWAL_ASSESSMENT:"+c.key(),Set.of("APPROVED_DECISION"),reasons);try{var decision=schema.renewalDecision(c.assessment().text());if(!c.key().equals(decision.conditionKey())||!c.group().equals(decision.group())||!c.outcome().equals(decision.outcome())||!c.criterion().sourceKeys().equals(decision.criterionSourceKeys())||!c.evidenceSourceKeys().equals(decision.evidenceSourceKeys()))reasons.add("RENEWAL_APPROVAL_CONTEXT_CONFLICT:"+c.key());}catch(Exception e){reasons.add("RENEWAL_APPROVAL_UNREADABLE:"+c.key());}if(!Set.of("SATISFIED","NOT_APPLICABLE").contains(c.outcome()))reasons.add("RENEWAL_CONDITION_UNRESOLVED:"+c.key());if(c.evidenceSourceKeys().isEmpty())reasons.add("RENEWAL_CONDITION_EVIDENCE_MISSING:"+c.key());if("SATISFIED".equals(c.outcome())){String nature=switch(c.group()){case "MANDATORY_STANDARD_UPDATE" -> "STANDARD_UPDATE";case "CONTINUING_STUDY" -> "CONTINUING_STUDY";case "CERTIFICATE_VALIDITY" -> "ORIGINAL_CERTIFICATE";default -> "CURRENT_DOCUMENT";};if(!hasNature(s,c.evidenceSourceKeys(),nature))reasons.add("RENEWAL_ACTUAL_EVIDENCE_MISSING:"+c.key());}}}
  var comparisons=out.putArray("consistency_checks");var groups=new LinkedHashMap<List<String>,List<ConsistencyValue>>();for(var c:s.consistency()){if(!c.value().equals(source(s,c.sourceKey()).literal()))reasons.add("CROSS_FILE_ORIGINAL_VALUE_MISMATCH:"+c.key());groups.computeIfAbsent(List.of(c.field(),c.model(),c.condition(),c.unit()),k->new ArrayList<>()).add(c);}for(var entry:groups.entrySet()){var values=entry.getValue();if(values.stream().map(ConsistencyValue::sourceKey).distinct().count()<2)reasons.add("CROSS_FILE_COMPARISON_INCOMPLETE_OR_CONDITIONS_DIFFER:"+String.join(":",entry.getKey()));boolean conflict=values.stream().map(ConsistencyValue::value).distinct().count()>1;comparisons.addObject().set("original_values",schema.tree(values));if(conflict)reasons.add("CROSS_FILE_CONFLICT:"+String.join(":",entry.getKey()));}for(String field:List.of("NAME_MODEL","STRUCTURE","SOFTWARE_VERSION","INTENDED_USE_CONTRAINDICATIONS","PERFORMANCE_TEST_COVERAGE","STERILITY_REUSE","SHELF_LIFE_STORAGE","REGISTRANT_MANUFACTURER","CERTIFICATE_TECHNICAL_REQUIREMENT_NUMBER"))if(s.consistency().stream().noneMatch(c->field.equals(c.field())))reasons.add("CROSS_FILE_CHECK_SCOPE_MISSING:"+field);
  out.set("required_body",schema.tree(s.body()));out.set("directory",schema.tree(s.directory()));if(s instanceof ChangeSelection c)out.set("change_impact",schema.tree(c.changes()));if(s instanceof RenewalSelection r)out.set("renewal_conditions",schema.tree(r.conditions()));out.put("blocked",!reasons.isEmpty());out.put("status",reasons.isEmpty()?"READY_FOR_PROFESSIONAL_REVIEW":"UNKNOWN");return out;
 }
 private static void checkHistory(Selection s,History h,String key,RegistrationLifecycleSchema schema,ArrayNode r){requireBody(s,"HISTORY",r);if(h.certificateNumber().isBlank()||h.originalSourceKey().isEmpty()||h.currentSourceKeys().isEmpty()||key.isEmpty()){r.add("ORIGINAL_CERTIFICATE_AND_COMPLETE_HISTORY_MISSING");return;}if(!"ORIGINAL_CERTIFICATE".equals(source(s,h.originalSourceKey()).nature()))r.add("ORIGINAL_CERTIFICATE_SOURCE_INVALID");for(String k:h.changeSourceKeys())if(!"CHANGE_RECORD".equals(source(s,k).nature()))r.add("HISTORICAL_CHANGE_SOURCE_INVALID:"+k);for(String k:h.currentSourceKeys())if(!"CURRENT_DOCUMENT".equals(source(s,k).nature()))r.add("CURRENT_DOCUMENT_SOURCE_INVALID:"+k);try{var src=source(s,key);var a=schema.historyApproval(src.literal());if(!"APPROVED_DECISION".equals(src.nature())||!"APPROVED".equals(a.outcome())||!h.certificateNumber().equals(a.certificateNumber())||!h.originalSourceKey().equals(a.originalSourceKey())||!h.changeSourceKeys().equals(a.changeSourceKeys())||!h.currentSourceKeys().equals(a.currentSourceKeys()))r.add("COMPLETE_REGISTRATION_HISTORY_NOT_CONFIRMED");}catch(Exception e){r.add("REGISTRATION_HISTORY_DECISION_UNREADABLE");}}
 private static Source source(Selection s,String key){return s.sources().stream().filter(x->key.equals(x.key())).findFirst().orElseThrow();}
 private static void requireFact(Selection s,Fact f,String key,Set<String> kinds,ArrayNode r){if(f.text().isBlank()||f.sourceKeys().stream().noneMatch(k->source(s,k).literal().equals(f.text())&&(kinds.isEmpty()||kinds.contains(source(s,k).nature()))))r.add("EXACT_SOURCE_FACT_MISSING:"+key);}
 private static boolean hasNature(Selection s,List<String> keys,String nature){return keys.stream().anyMatch(k->nature.equals(source(s,k).nature()));}
 private static void requireBody(Selection s,String key,ArrayNode r){if(s.body().stream().noneMatch(b->b.entityKeys().contains(key)))r.add("PATH_BODY_MISSING:"+key);}
 static JsonNode produce(TaskSourceVerifierInputAuthority.Verified input,JsonNode reads)throws Exception{
  var fixed=input.documentScenario();if(fixed==null||!supportsKind(fixed.required("selection").required("scenario_kind").asText()))return null;
  var schema=new RegistrationLifecycleSchema();var s=schema.read(fixed.required("selection"));var result=(ObjectNode)plan(fixed);var reasons=(ArrayNode)result.required("unknown_reasons");result.set("specification",fixed.required("specification"));result.put("selection_sha256",WireValues.sha256(ContentReadAuthorization.canonicalBytes(fixed.required("selection"))));
  var sections=input.target().candidate().nodeManifest().stream().filter(n->n.kind()==ArtifactProtocol.NodeKind.SECTION).map(ArtifactProtocol.NodeManifestItem::sectionId).toList();if(!sections.equals(input.input().targetSections())||!s.sectionIds().containsAll(sections))reasons.add("REGISTRATION_LIFECYCLE_SECTION_SCOPE_MISMATCH");
  var verified=new HashSet<String>();var sourceChecks=result.putArray("source_checks");
  for(var src:s.sources()){
   JsonNode found=null;for(var read:reads.required("sources"))if(schema.tree(src.evidence()).equals(read.required("evidence_ref"))){if(found!=null)throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);found=read;}
   boolean ok=found!=null&&found.path("access").asBoolean(false)&&found.path("located").asBoolean(false)&&found.path("complete").asBoolean(false)&&WireValues.sha256(src.literal().getBytes(StandardCharsets.UTF_8)).equals(found.path("literal_sha256").asText());
   var check=sourceChecks.addObject().put("source_key",src.key()).put("verified",ok);check.set("evidence",schema.tree(src.evidence()));if(found!=null)check.put("receipt_id",found.required("receipt_id").asText());if(ok)verified.add(src.key());else reasons.add("EXACT_SOURCE_NOT_VERIFIED:"+src.key());
  }
  var actual=new HashMap<String,JsonNode>();for(var node:input.target().body().required("nodes")){
   String id=node.required("node_id").asText();if(actual.put(id,node)!=null)throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);var manifest=input.target().candidate().nodeManifest().stream().filter(n->n.nodeId().equals(id)).findFirst().orElseThrow();
   if(Set.of("TEXT","TABLE","IMAGE","FORMULA").contains(node.required("content").path("kind").asText())&&s.body().stream().noneMatch(b->b.nodeId().equals(id)&&b.sectionId().equals(manifest.sectionId())&&b.content().equals(node.required("content"))))reasons.add("UNAPPROVED_REGISTRATION_LIFECYCLE_BODY:"+id);
  }
  var checks=result.putArray("body_checks");var bodyNodeIds=new HashMap<String,String>();
  for(var b:s.body()){
   if(!input.input().targetSections().contains(b.sectionId()))continue;
   var matches=new ArrayList<String>();for(var entry:actual.entrySet())if(b.nodeId().equals(entry.getKey())&&b.content().equals(entry.getValue().required("content"))&&input.target().candidate().nodeManifest().stream().anyMatch(n->n.nodeId().equals(entry.getKey())&&b.sectionId().equals(n.sectionId())))matches.add(entry.getKey());
   var check=checks.addObject().put("body_key",b.key()).put("exact_body",matches.size()==1);if(matches.size()!=1){reasons.add("REGISTRATION_LIFECYCLE_BODY_MISSING_OR_CONFLICT:"+b.key());continue;}String nodeId=matches.get(0);bodyNodeIds.put(b.key(),nodeId);check.put("node_id",nodeId);
   var required=new LinkedHashSet<>(b.sourceKeys());for(String key:b.entityKeys())required.addAll(entitySources(s,key));if(required.isEmpty())reasons.add("BODY_EVIDENCE_EMPTY:"+b.key());
   for(String key:required){if(!verified.contains(key))reasons.add("BODY_SOURCE_UNVERIFIED:"+b.key()+":"+key);boolean linked=false;for(var link:input.target().body().required("evidence_links"))if("SUPPORT".equals(link.path("relation").asText())&&schema.tree(source(s,key).evidence()).equals(link.required("evidence")))for(var id:link.required("node_ids"))if(nodeId.equals(id.asText()))linked=true;if(!linked)reasons.add("BODY_SUPPORT_CITATION_MISSING:"+b.key()+":"+key);}
  }
  // Each approved factual value must be present in body text for its entity, not merely in provenance.
  for(var b:s.body())if(input.input().targetSections().contains(b.sectionId()))for(String key:b.entityKeys()){
   String text=String.join(" ",s.body().stream().filter(x->b.sectionId().equals(x.sectionId())&&x.entityKeys().contains(key)&&bodyNodeIds.containsKey(x.key())).map(Body::text).toList());
   for(var fact:entityFacts(s,key))if(!fact.text().isBlank()&&!text.contains(fact.text()))reasons.add("ENTITY_FACT_BODY_MISMATCH:"+key);
  }
  for(var b:s.body())if(input.input().targetSections().contains(b.sectionId())){for(var d:s.directory())if(b.entityKeys().contains(d.key())&&!b.text().contains(d.title()))reasons.add("DIRECTORY_TITLE_BODY_MISMATCH:"+d.key());if(b.entityKeys().contains("HISTORY")){History h=s instanceof ChangeSelection c?c.history():s instanceof RenewalSelection r?r.history():null;if(h!=null&&!b.text().contains(h.certificateNumber()))reasons.add("CERTIFICATE_NUMBER_BODY_MISMATCH");}}
  result.set("verified_section_ids",schema.tree(input.input().targetSections()));result.put("coverage_mode","CURRENT_SECTION_CANDIDATE");result.put("blocked",!reasons.isEmpty());result.put("status",reasons.isEmpty()?"READY_FOR_PROFESSIONAL_REVIEW":"UNKNOWN");return result;
 }
 private static List<Fact> entityFacts(Selection s,String key){var values=new ArrayList<Fact>();if(s instanceof IvdSelection i&&"IVD_PRODUCT".equals(key)){values.add(i.intendedUse());values.add(i.reagentClassification());}if(s instanceof ChangeSelection c)for(var x:c.changes())if(key.equals(x.key()))values.addAll(changeFacts(x));if(s instanceof RenewalSelection r)for(var x:r.conditions())if(key.equals(x.key())){values.add(x.criterion());}return values;}
 private static Set<String> entitySources(Selection s,String key){var keys=new LinkedHashSet<String>();for(var f:entityFacts(s,key))keys.addAll(f.sourceKeys());if("PATH".equals(key))keys.addAll(s.pathDecision().sourceKeys());for(var d:s.directory())if(key.equals(d.key()))keys.addAll(d.basis().sourceKeys());if(s instanceof RenewalSelection renewal)for(var condition:renewal.conditions())if(key.equals(condition.key()))keys.addAll(condition.assessment().sourceKeys());if(!s.catalogueSourceKey().isEmpty())keys.add(s.catalogueSourceKey());for(var d:s.directory())if(key.equals(d.key()))keys.addAll(d.evidenceSourceKeys());if(s instanceof IvdSelection i&&"IVD_PRODUCT".equals(key)){keys.addAll(i.analyticalEvidenceSourceKeys());keys.addAll(i.clinicalEvidenceSourceKeys());}if(s instanceof ChangeSelection c){if("HISTORY".equals(key))historySources(keys,c.history(),c.historySourceKey());for(var x:c.changes())if(key.equals(x.key())){keys.addAll(x.beforeDocumentSourceKeys());keys.addAll(x.afterDocumentSourceKeys());}}if(s instanceof RenewalSelection r){if("HISTORY".equals(key))historySources(keys,r.history(),r.historySourceKey());for(var x:r.conditions())if(key.equals(x.key()))keys.addAll(x.evidenceSourceKeys());}return keys;}
 private static void historySources(Set<String> keys,History h,String approval){if(!approval.isEmpty())keys.add(approval);if(!h.originalSourceKey().isEmpty())keys.add(h.originalSourceKey());keys.addAll(h.changeSourceKeys());keys.addAll(h.currentSourceKeys());}
 static TaskSourceVerifierNormalizer.Normalized attach(TaskSourceVerifierNormalizer.Normalized n,JsonNode result){if(result==null)return n;var pins=(ObjectNode)n.pins();pins.set("registration_lifecycle",result);var f=n.findings();if(result.required("blocked").asBoolean())f=new ArtifactProtocol.ReviewFindings(f.targetKind(),f.targetRevision(),f.targetSha256(),f.ruleRevision(),f.requiredClaimIds(),f.requiredRuleIds(),f.claimChecks(),f.ruleChecks(),f.issueProposals(),false);pins.put("coverage_complete",f.coverageComplete());return new TaskSourceVerifierNormalizer.Normalized(f,pins);}
 static void consume(TaskSourceVerifierInputAuthority.Verified input,JsonNode provenance)throws Exception{if(!Objects.equals(produce(input,provenance.required("independent_reads")),provenance.required("normalization").get("registration_lifecycle")))throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
